import type {
  InkwellEntity,
  InkwellEntityType,
  InkwellNearestFromEntityTransformRequest,
  InkwellNearestRequest,
  InkwellEntitiesByIdsRequest,
} from './types';

const DEFAULT_BASE_URL = 'https://api.inkwell.ing/v1';

export interface InkwellClientOptions {
  apiKey?: string;
  baseUrl?: string;
  fetchImpl?: typeof fetch;
}

export class InkwellClient {
  private readonly apiKey: string | undefined;
  private readonly baseUrl: string;
  private readonly fetchImpl: typeof fetch;

  constructor(options: InkwellClientOptions = {}) {
    this.apiKey = options.apiKey;
    this.baseUrl = options.baseUrl ?? DEFAULT_BASE_URL;
    
    // Ensure fetch is correctly bound to the global (Window) to avoid Illegal invocation
    const boundGlobalFetch: typeof fetch | undefined = (() => {
      const g: any =
        typeof window !== 'undefined'
          ? window
          : typeof globalThis !== 'undefined'
          ? globalThis
          : undefined;
      if (g && typeof g.fetch === 'function') return g.fetch.bind(g);
      if (typeof fetch === 'function') return fetch.bind(undefined as any);
      return undefined;
    })();
    this.fetchImpl = options.fetchImpl ?? (boundGlobalFetch as typeof fetch);
  }

  private headers(): HeadersInit {
    const headers: Record<string, string> = {};
    if (this.apiKey) headers['x-api-key'] = this.apiKey;
    return headers;
  }

  private async doJson<T>(path: string, init?: RequestInit): Promise<T> {
    const res = await this.fetchImpl(`${this.baseUrl}${path}`, {
      ...init,
      headers: {
        ...(init?.headers || {}),
        ...this.headers(),
      },
    });
    if (!res.ok) {
      const text = await res.text().catch(() => '');
      throw new Error(
        `Inkwell ${path} failed: ${res.status} ${res.statusText} ${text}`
      );
    }
    const json: any = await res.json();
    if (json && typeof json === 'object' && 'ok' in json && 'data' in json) {
      return json.data as T;
    }
    return json as T;
  }

  getEntity(id: string): Promise<InkwellEntity> {
    return this.doJson(`/entity/${encodeURIComponent(id)}`);
  }

  getRandomEntity(types?: InkwellEntityType[]): Promise<InkwellEntity> {
    const qs = types && types.length ? `?types=${types.join(',')}` : '';
    return this.doJson(`/entity/random${qs}`);
  }

  getEmbeddingByEntityId(
    entityId: string
  ): Promise<{ embedding: number[]; entityId: string }> {
    return this.doJson(`/embedding/entity/${encodeURIComponent(entityId)}`);
  }

  nearestByEmbedding(req: InkwellNearestRequest): Promise<InkwellEntity[]> {
    return this.doJson(`/embedding/nearest`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(req),
    });
  }

  nearestFromEntityTransform(
    req: InkwellNearestFromEntityTransformRequest
  ): Promise<InkwellEntity[]> {
    return this.doJson(`/embedding/nearest-from-entity-transform`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(req),
    });
  }

  async entitiesByIds(
    req: InkwellEntitiesByIdsRequest
  ): Promise<InkwellEntity[]> {
    const response = await this.doJson(`/entities/by-ids`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(req),
    });
    return response?.items;
  }
}

export function createInkwellClient(options?: InkwellClientOptions) {
  return new InkwellClient(options);
}
